            if(!$canStore)throw new DomainException('Your role cannot issue school stock.');$requestId=(int)($_POST['request_id']??0);if(!$requestId)throw new DomainException('Choose an approved stock request.');$db->beginTransaction();$q=$db->prepare('SELECT r.*,i.item_name,i.quantity available,i.unit,i.last_unit_cost FROM inventory_requests r JOIN inventory_items i ON i.id=r.item_id WHERE r.id=? AND r.school_id=? FOR UPDATE');$q->execute([$requestId,$selected]);$request=$q->fetch();if(!$request||$request['status']!=='approved')throw new DomainException('Only approved stock requests in this school can be issued.');$available=(float)$request['available'];$quantity=(float)$request['quantity'];if($quantity>$available)throw new DomainException('The approved request exceeds current stock; receive stock or review the request amount.');$q=$db->prepare('UPDATE inventory_items SET quantity=quantity-?,updated_by=? WHERE id=? AND school_id=?');$q->execute([$quantity,$uid,$request['item_id'],$selected]);$q=$db->prepare("INSERT INTO inventory_movements(school_id,item_id,request_id,movement_type,quantity,unit_cost,balance_before,balance_after,note,recorded_by) VALUES(?,?,?,'issued',?,?,?,?,?,?)");$q->execute([$selected,$request['item_id'],$requestId,$quantity,$request['last_unit_cost'],$available,$available-$quantity,'Approved request #'.$requestId,$uid]);$q=$db->prepare("UPDATE inventory_requests SET status='issued' WHERE id=? AND school_id=? AND status='approved'");$q->execute([$requestId,$selected]);if($q->rowCount()!==1)throw new DomainException('This request was already issued or changed.');$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'issue','inventory_request',$requestId,json_encode(['school_id'=>$selected,'item_id'=>$request['item_id'],'quantity'=>$quantity,'balance_before'=>$available,'balance_after'=>$available-$quantity],JSON_THROW_ON_ERROR)]);$db->commit();$notice='Approved stock request issued and recorded as an inventory movement.';$tab='stock';
        }elseif($action==='move_stock'){
            if(!$canStore)throw new DomainException('Your role cannot record stock movements.');$itemId=(int)($_POST['item_id']??0);$type=(string)($_POST['movement_type']??'');$amount=filter_var($_POST['quantity']??null,FILTER_VALIDATE_FLOAT);$unitCostRaw=trim((string)($_POST['unit_cost']??''));$unitCost=$unitCostRaw===''?null:filter_var($unitCostRaw,FILTER_VALIDATE_FLOAT);$supplierId=(int)($_POST['supplier_id']??0);$note=trim((string)($_POST['note']??''));if(!$itemId||!in_array($type,['received','issued','adjusted'],true)||$amount===false||$amount<=0||$amount>100000000||mb_strlen($note)>255||($type==='adjusted'&&$note==='')||($supplierId>0&&$type!=='received')||($type==='received'&&($unitCost===false||$unitCost<=0||$unitCost>100000000)))throw new DomainException($type==='adjusted'?'Enter a physical count and a reason for the stocktake adjustment.':'Enter a valid stock movement, supplier, and quantity greater than zero.');if($supplierId){$q=$db->prepare("SELECT id FROM inventory_suppliers WHERE id=? AND school_id=? AND status='active'");$q->execute([$supplierId,$selected]);if(!$q->fetchColumn())throw new DomainException('Choose an active supplier in this school.');}
            $db->beginTransaction();$q=$db->prepare('SELECT id,item_name,quantity,unit,last_unit_cost FROM inventory_items WHERE id=? AND school_id=? FOR UPDATE');$q->execute([$itemId,$selected]);$item=$q->fetch();if(!$item)throw new DomainException('That item is outside this school.');$old=(float)$item['quantity'];$new=$type==='received'?$old+$amount:($type==='issued'?$old-$amount:$amount);if($new<0)throw new DomainException('Stock issued cannot exceed the available balance.');$q=$db->prepare('UPDATE inventory_items SET quantity=?,last_unit_cost=COALESCE(?,last_unit_cost),updated_by=? WHERE id=? AND school_id=?');$q->execute([$new,$type==='received'?$unitCost:null,$uid,$itemId,$selected]);$q=$db->prepare('INSERT INTO inventory_movements(school_id,item_id,supplier_id,movement_type,quantity,unit_cost,balance_before,balance_after,note,recorded_by) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$selected,$itemId,$supplierId?:null,$type,$amount,$type==='received'?$unitCost:$item['last_unit_cost'],$old,$new,$note?:null,$uid]);$movementId=(int)$db->lastInsertId();$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'record','inventory_movement',$movementId,json_encode(['school_id'=>$selected,'item_id'=>$itemId,'item'=>$item['item_name'],'type'=>$type,'quantity'=>$amount,'supplier_id'=>$supplierId?:null,'unit_cost'=>$type==='received'?$unitCost:$item['last_unit_cost'],'balance_before'=>$old,'balance_after'=>$new],JSON_THROW_ON_ERROR)]);$db->commit();$notice='Stock movement recorded.';$tab='stock';
        }else throw new DomainException('Choose a valid operation.');
    }catch(DomainException $ex){if($db->inTransaction())$db->rollBack();$error=$ex->getMessage();}catch(Throwable $ex){if($db->inTransaction())$db->rollBack();$error='The operation could not be saved. Apply the latest database migration and check school access.';}
}
