ms i ON i.id=m.item_id JOIN users u ON u.id=m.recorded_by LEFT JOIN inventory_suppliers s ON s.id=m.supplier_id AND s.school_id=m.school_id WHERE m.school_id=? ORDER BY m.created_at DESC LIMIT 60');$q->execute([$selected]);$movements=$q->fetchAll();}
