php endforeach;?></tbody></table></div><p class="ops-actions"><button class="button primary" type="submit">Save class register</button></p></form><?php else:?><div class="empty-state"><h3>No pupils in this class yet</h3><p>Register pupils in the school directory before taking attendance.</p></div><?php endif;?></section>
<section class="content-section" data-attendance-report data-api="api/attendance_report.php" data-school="<?=$selected?>"><div class="section-heading"><div><div class="eyebrow">ATTENDANCE SUMMARY</div><h2>Attendance report</h2><p class="muted">Recorded pupil marks by class and date. Excused marks are reported separately.</p></div></div><form class="ops-filter" data-attendance-report-filter><input type="hidden" name="school_id" value="<?=$selected?>"><div><label for="attendance-report-class">Class</label><select id="attendance-report-class" name="class_level"><option value="">All permitted classes</option><?php foreach($classes as $c):?><option value="<?=e($c['name'])?>"<?=$classFilter===$c['name']?' selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div><label for="attendance-report-start">From</label><input id="attendance-report-start" type="date" name="start_date" value="<?=e(date('Y-m-d',strtotime('-29 days')))?>" required></div><div><label for="attendance-report-end">To</label><input id="attendance-report-end" type="date" name="end_date" value="<?=e($today)?>" required></div><button class="button" type="submit">Load report</button></form><div data-attendance-report-output aria-live="polite"><p class="muted">Loading attendance summary�</p></div></section><?php elseif($tab==='contracts'&&$canContracts):?><section class="note-create"><div class="section-heading"><div><div class="eyebrow">HUMAN RESOURCES</div><h2><?=isset($_GET['renew'])?'Renew staff contract':(isset($_GET['edit'])?'Update staff contract':'Record a staff contract')?></h2></div></div><?php $editContract=null;$renewContract=null;if(isset($_GET['edit']))foreach($contracts as $c)if((int)$c['id']===(int)$_GET['edit'])$editContract=$c;if(isset($_GET['renew']))foreach($contracts as $c)if((int)$c['id']===(int)$_GET['renew']&&empty($c['has_renewal'])&&$c['status']!=='renewed')$renewContract=$c;$renewStart=$renewContract?date('Y-m-d',strtotime($renewContract['end_date'].' +1 day')):$today;?><?php if(!$staff):?><p class="muted">No linked staff accounts are available for contracts.</p><?php else:?><form method="post" class="note-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="<?= $renewContract?'renew_contract':'save_contract' ?>"><input type="hidden" name="school_id" value="<?=$selected?>"><input type="hidden" name="contract_id" value="<?=e((string)($editContract['id']??0))?>"><input type="hidden" name="renewed_from_id" value="<?=e((string)($renewContract['id']??0))?>"><div class="form-grid"><div><label for="contract-staff">Staff member</label><select id="contract-staff" name="user_id" required><?php foreach($staff as $p):?><option value="<?=$p['id']?>"<?=((int)($editContract['user_id']??$renewContract['user_id']??0)===(int)$p['id'])?' selected':''?>><?=e($p['name'].' · '.str_replace('_',' ',$p['role']))?></option><?php endforeach;?></select></div><div><label for="contract-start">Start date</label><input id="contract-start" type="date" name="start_date" value="<?=e((string)($editContract['start_date']??($renewContract?$renewStart:$today)))?>" required></div><div><label for="contract-end">End date</label><input id="contract-end" type="date" name="end_date" value="<?=e((string)($editContract['end_date']??''))?>" required></div><div><label for="contract-terms">Terms or notes</label><textarea id="contract-terms" name="terms" rows="3" maxlength="5000"><?=e((string)($editContract['terms']??$renewContract['terms']??''))?></textarea></div></div><button class="button primary" type="submit"><?=$renewContract?'Create renewal':'Save contract'?></button></form><?php endif;?></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">STAFF RECORDS</div><h2>Contracts</h2><p class="muted">Expiry is calculated from each end date.</p></div><span class="count-pill"><?=count($contracts)?> contracts</span></div><?php if($contracts):?><div class="table-wrap"><table><thead><tr><th>Staff member</th><th>Role</th><th>Term</th><th>Status</th><th>Terms</th><th></th></tr></thead><tbody><?php foreach($contracts as $c):?><tr><td><?=e($c['staff_name'])?></td><td><?=e(str_replace('_',' ',$c['role']))?></td><td><?=e(date('j M Y',strtotime($c['start_date'])))?> – <?=e(date('j M Y',strtotime($c['end_date'])))?></td><td><?=e($c['status']==='renewed'?'Renewed':(strtotime($c['end_date'])<strtotime($today)?'Ended':(strtotime($c['end_date'])<=strtotime('+30 days')?'Ending soon':'Active')))?></td><td><?=e($c['terms']?:'—')?></td><td><a class="button" href="?tab=contracts&amp;school_id=<?=$selected?>&amp;edit=<?=$c['id']?>">Edit</a><?php if(empty($c['has_renewal'])&&$c['status']!=='renewed'):?> <a class="button" href="?tab=contracts&amp;school_id=<?=$selected?>&amp;renew=<?=$c['id']?>">Renew</a><?php endif;?><?php if(!empty($c['renewed_from_id'])):?> <span class="muted">Renewal of #<?=e((string)$c['renewed_from_id'])?></span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No contracts recorded</h3><p>Add a contract for a linked staff account to keep its term and expiry visible.</p></div><?php endif;?></section>
<?php elseif($tab==='leave'&&$canLeave):?><section class="note-create"><div class="section-heading"><div><div class="eyebrow">STAFF SERVICES</div><h2>Request leave</h2><p class="muted">Requests are reviewed by HR or a school manager. Leave dates do not become approved until reviewed.</p></div></div><form method="post" class="note-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_leave_request"><input type="hidden" name="school_id" value="<?=$selected?>"><div class="form-grid"><div><label for="leave-type">Leave type</label><select id="leave-type" name="leave_type" required><?php foreach(['annual'=>'Annual','sick'=>'Sick','maternity'=>'Maternity','paternity'=>'Paternity','compassionate'=>'Compassionate','other'=>'Other'] as $k=>$v):?><option value="<?=$k?>"><?=$v?></option><?php endforeach;?></select></div><div><label for="leave-start">Start date</label><input id="leave-start" type="date" name="start_date" required></div><div><label for="leave-end">End date</label><input id="leave-end" type="date" name="end_date" required></div><div><label for="leave-reason">Reason</label><textarea id="leave-reason" name="reason" maxlength="2000" rows="3"></textarea></div></div><button class="button primary" type="submit">Submit request</button></form></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">LEAVE RECORDS</div><h2><?=($canReviewLeave?'School leave requests':'My leave requests')?></h2></div><span class="count-pill"><?=count($leaveRequests)?> requests</span></div><?php if($leaveRequests):?><div class="table-wrap"><table><thead><tr><th>Staff member</th><th>Type</th><th>Dates</th><th>Reason</th><th>Status</th><th>Review note</th><?php if($canReviewLeave):?><th>Action</th><?php endif;?></tr></thead><tbody><?php foreach($leaveRequests as $leave):?><tr><td><?=e($canReviewLeave?$leave['staff_name']:'You')?></td><td><?=e(ucfirst($leave['leave_type']))?></td><td><?=e(date('j M Y',strtotime($leave['start_date'])).' – '.date('j M Y',strtotime($leave['end_date'])))?></td><td><?=e($leave['reason']?:'—')?></td><td><?=e(ucfirst($leave['status']))?><?php if(!$canReviewLeave&&$leave['status']==='pending'):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="cancel_leave_request"><input type="hidden" name="school_id" value="<?=$selected?>"><input type="hidden" name="request_id" value="<?=$leave['id']?>"><button class="button danger" type="submit">Cancel request</button></form><?php endif;?></td><td><?=e($leave['review_note']?:'—')?></td><?php if($canReviewLeave):?><td><?php if($leave['status']==='pending'&&(int)$leave['user_id']!==$uid):?><form method="post" class="stock-movement"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="review_leave_request"><input type="hidden" name="school_id" value="<?=$selected?>"><input type="hidden" name="request_id" value="<?=$leave['id']?>"><input name="review_note" maxlength="1000" placeholder="Review note"><button class="button" name="decision" value="approved">Approve</button><button class="button danger" name="decision" value="rejected">Reject</button></form><?php elseif($leave['status']==='pending'&&(int)$leave['user_id']===$uid):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="cancel_leave_request"><input type="hidden" name="school_id" value="<?=$selected?>"><input type="hidden" name="request_id" value="<?=$leave['id']?>"><button class="button danger" type="submit">Cancel request</button></form><?php endif;?></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No leave requests</h3><p>Submitted leave requests and their review status will appear here.</p></div><?php endif;?></section>
<?php elseif($tab==='stock'&&$canStore):?><section class="note-create"><div class="section-heading"><div><div class="eyebrow">STOREKEEPING</div><h2>Add stock item</h2></div></div><form method="post" class="note-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_item"><input type="hidden" name="school_id" value="<?=$selected?>"><div class="form-grid"><div><label for="stock-name">Item name</label><input id="stock-name" name="item_name" maxlength="160" required></div><div><label for="stock-category">Category <span class="muted">(optional)</span></label><select id="stock-category" name="category_id"><option value="0">Uncategorized</option><?php foreach($categories as $category):if($category['status']==='active'):?><option value="<?=$category['id']?>"><?=e($category['name'])?></option><?php endif;endforeach;?></select></div><div><label for="stock-threshold">Reorder threshold <span class="muted">(optional)</span></label><input id="stock-threshold" name="reorder_threshold" type="number" min="0" step="0.01" placeholder="Alert when at or below"></div><div><label for="stock-unit">Unit</label><input id="stock-unit" name="unit" maxlength="30" value="item" required></div></div><button class="button primary" type="submit">Add item</button></form></section><section class="note-create"><div class="section-heading"><div><div class="eyebrow">STOCK CATEGORIES</div><h2>Manage categories</h2><p class="muted">Categories belong to this school. Deactivating one keeps existing stock assignments and history.</p></div></div><form method="post" class="note-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_category"><input type="hidden" name="school_id" value="<?=$selected?>"><div class="form-grid"><div><label for="stock-category-name">Category name</label><input id="stock-category-name" name="name" maxlength="100" required></div></div><button class="button primary" type="submit">Add category</button></form><?php if($categories):?><div class="table-wrap"><table><thead><tr><th>Category</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($categories as $category):?><tr><td><?=e($category['name'])?></td><td><?=e(ucfirst($category['status']))?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle_category"><input type="hidden" name="school_id" value="<?=$selected?>"><input type="hidden" name="category_id" value="<?=$category['id']?>"><button class="button" type="submit"><?=$category['status']==='active'?'Deactivate':'Reactivate'?></button></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p class="muted">No categories have been added.</p><?php endif;?></section><section class="note-create"><div class="section-heading"><div><div class="eyebrow">SUPPLIER DIRECTORY</div><h2>School suppliers</h2><p class="muted">Supplier records are scoped to this school. Contact details are optional.</p></div></div><form method="post" class="note-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_supplier"><input type="hidden" name="school_id" value="<?=$selected?>"><div class="form-grid"><div><label for="supplier-name">Supplier name</label><input id="supplier-name" name="name" maxlength="160" required></div><div><label for="supplier-contact">Contact person</label><input id="supplier-contact" name="contact_name" maxlength="140"></div><div><label for="supplier-phone">Phone</label><input id="supplier-phone" name="phone" type="tel" maxlength="40"></div><div><label for="supplier-email">Email</label><input id="supplier-email" name="email" type="email" maxlength="190"></div></div><button class="button" type="submit">Add supplier</button></form><?php if($suppliers):?><div class="table-wrap"><table><thead><tr><th>Supplier</th><th>Contact</th><th>Phone / email</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($suppliers as $supplier):?><tr><td><?=e($supplier['name'])?></td><td><?=e($supplier['contact_name']?:'-')?></td><td><?=e(trim(($supplier['phone']?:'').' '.($supplier['email']?:''))?:'-')?></td><td><?=e(ucfirst($supplier['status']))?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle_supplier"><input type="hidden" name="school_id" value="<?=$selected?>"><input type="hidden" name="supplier_id" value="<?=$supplier['id']?>"><button class="button" type="submit"><?=$supplier['status']==='active'?'Deactivate':'Reactivate'?></button></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p class="muted">No suppliers have been added.</p><?php endif;?></section><section class="note-create"><div class="section-heading"><div><div class="eyebrow">STOCK WORKFLOW</div><h2>Request stock</h2><p class="muted">Requests require school manager approval before an issue can be recorded.</p></div></div><form method="post" class="note-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="request_stock"><input type="hidden" name="school_id" value="<?=$selected?>"><div class="form-grid"><div><label for="request-item">Item</label><select id="request-item" name="item_id" required><?php foreach($items as $item):?><option value="<?=$item['id']?>"><?=e($item['item_name'].' · available '.number_format((float)$item['quantity'],2).' '.$item['unit'])?></option><?php endforeach;?></select></div><div><label for="request-quantity">Quantity requested</label><input id="request-quantity" type="number" name="quantity" min="0.01" step="0.01" required></div><div><label for="request-note">Purpose</label><input id="request-note" name="request_note" maxlength="255"></div></div><button class="button primary" type="submit">Submit request</button></form></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">REQUESTS & APPROVALS</div><h2>Stock request queue</h2></div><span class="count-pill"><?=count($requests)?> requests</span></div><?php if($requests):?><div class="table-wrap"><table><thead><tr><th>Requested</th><th>Item</th><th>Quantity</th><th>Requested by</th><th>Status</th><th>Review note</th><th>Action</th></tr></thead><tbody><?php foreach($requests as $request):?><tr><td><?=e(date('j M Y H:i',strtotime($request['created_at'])))?></td><td><?=e($request['item_name'])?></td><td><?=e(number_format((float)$request['quantity'],2).' '.$request['unit'])?></td><td><?=e($request['requester'])?></td><td><?=e(ucfirst($request['status']))?></td><td><?=e($request['review_note']?:$request['request_note']?:'—')?></td><td><?php if($request['status']==='pending'&&in_array($role,$schoolManagers,true)):?><form method="post" class="stock-movement"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="review_stock_request"><input type="hidden" name="school_id" value="<?=$selected?>"><input type="hidden" name="request_id" value="<?=$request['id']?>"><input name="review_note" maxlength="255" placeholder="Optional note"><button class="button" name="decision" value="approved">Approve</button><button class="button danger" name="decision" value="rejected">Reject</button></form><?php elseif($request['status']==='approved'&&$canStore):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="issue_stock_request"><input type="hidden" name="school_id" value="<?=$selected?>"><input type="hidden" name="request_id" value="<?=$request['id']?>"><button class="button primary" type="submit">Issue stock</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No stock requests</h3><p>Submit a request when a department needs stock. School managers can approve or reject it.</p></div><?php endif;?></section><?php if($lowStock):?><div class="notice error" role="status"><strong>Low stock:</strong> <?php foreach($lowStock as $low):?><span><?=e($low['item_name'])?> (<?=e(number_format((float)$low['quantity'],2))?> / threshold <?=e(number_format((float)$low['reorder_threshold'],2))?> <?=e($low['unit'])?>)</span><?php endforeach;?></div><?php endif;?><section class="content-section"><div class="section-heading"><div><div class="eyebrow">CURRENT BALANCE</div><h2>Stock items</h2><p><a class="button" href="stocktakes.php?school_id=<?=$selected?>">Manage stocktakes</a></p></div><span class="count-pill"><?=count($items)?> items · estimated value KES <?=e(number_format($valuedStock,2))?><?= $unvaluedStock?' · '.$unvaluedStock.' with no receipt cost':'' ?></span></div><?php if($items):?><div class="table-wrap"><table><thead><tr><th>Item</th><th>Category</th><th>Balance</th><th>Latest receipt cost</th><th>Estimated value</th><th>Category / reorder threshold</th><th>Unit</th><th>Record movement</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?=e($item['item_name'])?></td><td><?=e($item['category_name']?:'Uncategorized'.($item['category_status']==='inactive'?' (inactive)':''))?></td><td><?=e(number_format((float)$item['quantity'],2))?><?php if($item['reorder_threshold']!==null&&(float)$item['quantity']<=(float)$item['reorder_threshold']):?> <span class="count-pill">Low</span><?php endif;?></td><td><?=$item['last_unit_cost']===null?'—':'KES '.e(number_format((float)$item['last_unit_cost'],2))?></td><td><?=$item['last_unit_cost']===null?'Unvalued':'KES '.e(number_format((float)$item['quantity']*(float)$item['last_unit_cost'],2))?></td><td><?=$item['reorder_threshold']===null?'�':e(number_format((float)$item['reorder_threshold'],2))?></td><td><form method="post" class="stock-movement"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_item"><input type="hidden" name="school_id" value="<?=$selected?>"><input type="hidden" name="item_id" value="<?=$item['id']?>"><select name="category_id" aria-label="Category for <?=e($item['item_name'])?>"><option value="0"<?=empty($item['category_id'])?' selected':''?>>Uncategorized</option><?php foreach($categories as $category):if($category['status']==='active'||(int)$category['id']===(int)($item['category_id']??0)):?><option value="<?=$category['id']?>"<?=(int)$category['id']===(int)($item['category_id']??0)?' selected':''?>><?=e($category['name'].($category['status']==='inactive'?' (inactive - retained)':''))?></option><?php endif;endforeach;?></select><input type="hidden" name="item_name" value="<?=e($item['item_name'])?>"><input type="hidden" name="unit" value="<?=e($item['unit'])?>"><input aria-label="Reorder threshold for <?=e($item['item_name'])?>" type="number" min="0" step="0.01" name="reorder_threshold" value="<?=e((string)($item['reorder_threshold']??''))?>" placeholder="Not set"><button class="button" type="submit">Save alert</button></form></td><td><?=e($item['unit'])?></td><td><form method="post" class="stock-movement"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="move_stock"><input type="hidden" name="school_id" value="<?=$selected?>"><input type="hidden" name="item_id" value="<?=$item['id']?>"><select name="movement_type" aria-label="Movement type"><option value="received">Received</option><option value="issued">Issued</option><option value="adjusted">Physical count / adjust</option></select><select name="supplier_id" data-supplier-select aria-label="Supplier for stock receipt"><option value="">No supplier selected</option><?php foreach($suppliers as $supplier):if($supplier['status']==='active'):?><option value="<?=$supplier['id']?>"><?=e($supplier['name'])?></option><?php endif;endforeach;?></select><input type="number" step="0.01" min="0.01" name="quantity" placeholder="Quantity" aria-label="Quantity" required><input type="number" step="0.01" min="0.01" name="unit_cost" placeholder="Unit cost (required for receipt)" aria-label="Unit cost required for receipt"><input name="note" maxlength="255" placeholder="Reason (required for physical count)" aria-label="Reason (required for physical count)"><button class="button" type="submit">Record</button></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No stock items yet</h3><p>Add an item, then record receipts, issues or a verified balance adjustment.</p></div><?php endif;?></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">MOVEMENT HISTORY</div><h2>Recent stock activity</h2></div></div><?php if($movements):?><div class="table-wrap"><table><thead><tr><th>Date</th><th>Item</th><th>Movement</th><th>Quantity / count</th><th>Before</th><th>After</th><th>Supplier</th><th>Recorded by</th><th>Note</th></tr></thead><tbody><?php foreach($movements as $m):?><tr><td><?=e(date('j M Y H:i',strtotime($m['created_at'])))?></td><td><?=e($m['item_name'])?></td><td><?=e(ucfirst($m['movement_type']))?></td><td><?=e(number_format((float)$m['quantity'],2))?></td><td><?=$m['balance_before']===null?'&mdash;':e(number_format((float)$m['balance_before'],2))?></td><td><?=$m['balance_after']===null?'&mdash;':e(number_format((float)$m['balance_after'],2))?></td><td><?=e($m['supplier_name']?:'&mdash;')?></td><td><?=e($m['recorded_by_name'])?></td><td><?=e($m['note']?:'—')?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p class="muted">No stock movements recorded yet.</p><?php endif;?></section><?php endif;?>
<footer class="page-footer">ShuleLite <span>·</span> School operations</footer></div></main></div></body></html>
